for(let b of document.querySelectorAll('[data-tab]'))b.querySelector('span').innerHTML=icons[b.dataset.tab];
$('#locate').innerHTML=icons.home;$('#show-buses').innerHTML=icons.lines;$('#correct-location').innerHTML=svg('<path d="m14 4 6 6-10 10-7 1 1-7 10-10zM11 7l6 6"/>');
